create table if not exists public.houses (id text primary key,name text not null,captain text default '',created_at timestamptz default now());
create table if not exists public.athletes (id text primary key,first_name text not null,last_name text not null,student_id text default '',house_id text not null references public.houses(id) on delete cascade,gender text default '',programme text default '',division text default '',created_at timestamptz default now());
create table if not exists public.events (id text primary key,name text not null,category text default '',division text default '',created_at timestamptz default now());
create table if not exists public.results (id text primary key,event_id text not null references public.events(id) on delete cascade,athlete_id text not null references public.athletes(id) on delete cascade,house_id text not null references public.houses(id) on delete cascade,event_date date,position integer not null,points numeric not null default 0,created_at timestamptz default now());
create table if not exists public.championship_settings (id integer primary key,year integer not null default 2026,points jsonb not null default '{"1":10,"2":7,"3":5,"4":3,"5":2,"6":1}'::jsonb,updated_at timestamptz default now());
alter table public.houses enable row level security; alter table public.athletes enable row level security; alter table public.events enable row level security; alter table public.results enable row level security; alter table public.championship_settings enable row level security;
drop policy if exists "public read houses" on public.houses; drop policy if exists "public write houses" on public.houses; create policy "public read houses" on public.houses for select to anon,authenticated using (true); create policy "public write houses" on public.houses for all to anon,authenticated using (true) with check (true);
drop policy if exists "public read athletes" on public.athletes; drop policy if exists "public write athletes" on public.athletes; create policy "public read athletes" on public.athletes for select to anon,authenticated using (true); create policy "public write athletes" on public.athletes for all to anon,authenticated using (true) with check (true);
drop policy if exists "public read events" on public.events; drop policy if exists "public write events" on public.events; create policy "public read events" on public.events for select to anon,authenticated using (true); create policy "public write events" on public.events for all to anon,authenticated using (true) with check (true);
drop policy if exists "public read results" on public.results; drop policy if exists "public write results" on public.results; create policy "public read results" on public.results for select to anon,authenticated using (true); create policy "public write results" on public.results for all to anon,authenticated using (true) with check (true);
drop policy if exists "public read settings" on public.championship_settings; drop policy if exists "public write settings" on public.championship_settings; create policy "public read settings" on public.championship_settings for select to anon,authenticated using (true); create policy "public write settings" on public.championship_settings for all to anon,authenticated using (true) with check (true);
insert into public.championship_settings(id,year) values (1,2026) on conflict (id) do nothing;
insert into public.houses(id,name,captain) values ('h1','House 1',''),('h2','House 2',''),('h3','House 3',''),('h4','House 4','') on conflict (id) do nothing;
